    42      template <class CharT, class Sink>
    43      std::size_t escape_string(const CharT* s, std::size_t length,
    44                           bool escape_all_non_ascii, bool escape_solidus,
    45                           Sink& sink)
    46      {
    47          std::size_t count = 0;
    48          const CharT* begin = s;
    49          const CharT* end = s + length;
    50          for (const CharT* it = begin; it != end; ++it)
    51          {
    52              CharT c = *it;
    53              switch (c)
    54              {
    55                  case '\\':
    56                      sink.push_back('\\');
    57                      sink.push_back('\\');
    58                      count += 2;
    59                      break;
    60                  case '"':
    61                      sink.push_back('\\');
    62                      sink.push_back('\"');
    63                      count += 2;
    64                      break;
    65                  case '\b':
    66                      sink.push_back('\\');
    67                      sink.push_back('b');
    68                      count += 2;
    69                      break;
    70                  case '\f':
    71                      sink.push_back('\\');
    72                      sink.push_back('f');
    73                      count += 2;
    74                      break;
    75                  case '\n':
    76                      sink.push_back('\\');
    77                      sink.push_back('n');
    78                      count += 2;
    79                      break;
    80                  case '\r':
    81                      sink.push_back('\\');
    82                      sink.push_back('r');
    83                      count += 2;
    84                      break;
    85                  case '\t':
    86                      sink.push_back('\\');
    87                      sink.push_back('t');
    88                      count += 2;
    89                      break;
    90                  default:
    91                      if (escape_solidus && c == '/')
    92                      {
    93                          sink.push_back('\\');
    94                          sink.push_back('/');
    95                          count += 2;
    96                      }
    97                      else if (is_control_character(c) || escape_all_non_ascii)
    98                      {
    99                          // convert to codepoint
   100                          uint32_t cp;
   101                          auto r = unicode_traits::to_codepoint(it, end, cp, unicode_traits::conv_flags::strict);
   102                          //unicode_traits::sequence_generator<const CharT*> g(it, end, unicode_traits::conv_flags::strict);
   103                          //if (g.done() || g.status() != unicode_traits::conv_errc())
   104                          if (r.ec != unicode_traits::conv_errc())
   105                          {
   106                              JSONCONS_THROW(ser_error(json_errc::illegal_codepoint));
   107                          }
   108                          //uint32_t cp = g.get().codepoint();
   109                          //it += (g.get().length() - 1);
   110                          it = r.ptr;
   111                          if (is_non_ascii_codepoint(cp) || is_control_character(c))
   112                          {
   113                              if (cp > 0xFFFF)
   114                              {
   115                                  cp -= 0x10000;
   116                                  uint32_t first = (cp >> 10) + 0xD800;
   117                                  uint32_t second = ((cp & 0x03FF) + 0xDC00);
   118
   119                                  sink.push_back('\\');
   120                                  sink.push_back('u');
   580          }
