   652          bool visit_string(const string_view_type& sv, semantic_tag tag, const ser_context&, std::error_code&) override
   653          {
   654              if (!stack_.empty())
   655              {
   656                  if (stack_.back().is_array())
   657                  {
   658                      begin_scalar_value();
   659                  }
   660                  if (!stack_.back().is_multi_line() && column_ >= options_.line_length_limit())
   661                  {
   662                      break_line();
   663                  }
   664              }
   665
   666              switch (tag)
   667              {
   668                  case semantic_tag::bigint:
   669                      write_bigint_value(sv);
   670                      break;
   671                  default:
   672                  {
   673                      sink_.push_back('\"');
   674                      std::size_t length = jsoncons::detail::escape_string(sv.data(), sv.length(),options_.escape_all_non_ascii(),options_.escape_solidus(),sink_);
   675                      sink_.push_back('\"');
   676                      column_ += (length+2);
   677                      break;
   678                  }
   679              }
   680
   681              end_value();
   682              return true;
