  1238          void write_bigint_value(const string_view_type& sv)
  1239          {
  1240              switch (options_.bigint_format())
  1241              {
  1242                  case bigint_chars_format::number:
  1243                  {
  1244                      sink_.append(sv.data(),sv.size());
  1245                      break;
  1246                  }
  1247                  case bigint_chars_format::base64:
  1248                  {
  1249                      bigint n = bigint::from_string(sv.data(), sv.length());
  1250                      bool is_neg = n < 0;
  1251                      if (is_neg)
  1252                      {
  1253                          n = - n -1;
  1254                      }
  1255                      int signum;
  1256                      std::vector<uint8_t> v;
  1257                      n.write_bytes_be(signum, v);
  1258
  1259                      sink_.push_back('\"');
  1260                      if (is_neg)
  1261                      {
  1262                          sink_.push_back('~');
  1263                      }
  1264                      encode_base64(v.begin(), v.end(), sink_);
  1265                      sink_.push_back('\"');
  1266                      break;
  1267                  }
  1268                  case bigint_chars_format::base64url:
  1269                  {
  1270                      bigint n = bigint::from_string(sv.data(), sv.length());
  1271                      bool is_neg = n < 0;
  1272                      if (is_neg)
  1273                      {
  1274                          n = - n -1;
  1275                      }
  1276                      int signum;
  1277                      std::vector<uint8_t> v;
  1278                      n.write_bytes_be(signum, v);
  1279
  1280                      sink_.push_back('\"');
  1281                      if (is_neg)
  1282                      {
  1283                          sink_.push_back('~');
  1284                      }
  1285                      encode_base64url(v.begin(), v.end(), sink_);
  1286                      sink_.push_back('\"');
  1287                      break;
  1288                  }
  1289                  default:
  1290                  {
  1291                      sink_.push_back('\"');
  1292                      sink_.append(sv.data(),sv.size());
  1293                      sink_.push_back('\"');
  1294                      break;
  1295                  }
  1296              }
  1297          }
